        elif tokens[0].value == "NULL":
            consume(TokenType.KEYWORD)
            return Literal(None)
        elif tokens[0].type == TokenType.IDENTIFIER:
            return ColumnRef(consume(TokenType.IDENTIFIER).value)
        elif tokens[0].type == TokenType.OPERATOR and tokens[0].value == '(':  # (
            consume(TokenType.OPERATOR)
            expr = _parse_or_expr()
            consume(TokenType.OPERATOR)  # )
            return expr
        else:
            raise SQLSyntaxError(f"Unexpected token in primary: {tokens[0].value}")

    def _parse_not_expr() -> Expr:
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            consume(TokenType.KEYWORD)
            return Not(_parse_not_expr())
        return _parse_primary()

    def _parse_and_expr() -> Expr:
        expr = _parse_not_expr()
        while tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
            consume(TokenType.KEYWORD)
            expr = And(expr, _parse_not_expr())
        return expr

    def _parse_or_expr() -> Expr:
        expr = _parse_and_expr()
        while tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
            consume(TokenType.KEYWORD)
            expr = Or(expr, _parse_and_expr())
        return expr

    def _parse_predicate() -> Expr:
        expr = _parse_primary()
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
            op = consume(TokenType.OPERATOR).value
            right = _parse_primary()
            return Comparison(op, expr, right)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
            consume(TokenType.KEYWORD)
            negated = False
            if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
                consume(TokenType.KEYWORD)
                negated = True
            consume(TokenType.KEYWORD)  # NULL
            return IsNull(expr, negated)
        else:
            return expr

    idx = 0
    def consume(expected_type: TokenType):
        nonlocal idx
        if idx >= len(tokens) or tokens[idx].type != expected_type:
            raise SQLSyntaxError(f"Expected {expected_type}, got {tokens[idx].type}")
        token = tokens[idx]
        idx += 1
        return token

    expr = _parse_or_expr()
    if idx < len(tokens) and tokens[idx].type != TokenType.EOF:
        raise SQLSyntaxError(f"Trailing tokens after expression: {tokens[idx].value}")

    return expr
